import numpy as np
# 두 걸음짜리 장난감 언어 모델: P(다음 | 직전)
P = {'<s>': {'a': .6, 'b': .4},
     'a': {'x': .5, 'y': .5},
     'b': {'z': .9, 'w': .1}}
def greedy(s='<s>', n=2):
    out, logp = [], 0.0
    for _ in range(n):
        tok, p = max(P[s].items(), key=lambda kv: kv[1])
        out.append(tok); logp += np.log(p); s = tok
    return out, round(float(np.exp(logp)), 2)
def beam(k, n=2):
    beams = [(['<s>'], 0.0)]                      # (경로, 누적 비용 = Σ -log p)
    for _ in range(n):
        cand = [(path + [t], c - np.log(p))
                for path, c in beams for t, p in P[path[-1]].items()]
        beams = sorted(cand, key=lambda b: b[1])[:k]
    return beams[0][0][1:], round(float(np.exp(-beams[0][1])), 2)
print("greedy      ", greedy())
print("beam k=1    ", beam(1))
print("beam k=2    ", beam(2))
rng = np.random.default_rng(0); s, out = '<s>', []
for _ in range(2):
    toks, ps = zip(*P[s].items()); s = rng.choice(toks, p=ps); out.append(str(s))
print("sampling    ", out)

from collections import Counter
corpus = "input output inputs put in an input".split()
words = Counter(tuple(w) + ('_',) for w in corpus)       # '_' = 단어 끝 표시
vocab = {c for w in words for c in w}
merges = []
for _ in range(5):
    pairs = Counter()
    for w, n in words.items():
        for a, b in zip(w, w[1:]):
            pairs[a, b] += n
    (a, b), cnt = pairs.most_common(1)[0]                # 가장 잦은 이웃 쌍
    merges.append((a + b, cnt)); vocab.add(a + b)
    new = Counter()
    for w, n in words.items():
        out, i = [], 0
        while i < len(w):
            if i + 1 < len(w) and (w[i], w[i+1]) == (a, b):
                out.append(a + b); i += 2
            else:
                out.append(w[i]); i += 1
        new[tuple(out)] += n
    words = new
print("병합 순서:", merges)
print("어휘 크기:", len(vocab))
print("분절 결과:", list(words))
